<?php
namespace Tests\Feature;
use App\Models\{ApprovalHistory,Department,EditRequest,Leave,TimeClock,User};use Illuminate\Foundation\Testing\RefreshDatabase;use Illuminate\Support\Facades\Event;use Tests\TestCase;
class ManagementWorkflowTest extends TestCase {use RefreshDatabase;private function user(string $email,string $role,array $extra=[]):User{return User::create(['name'=>$email,'email'=>$email,'password'=>'password','role'=>$role,'shift_time'=>'18:00','employeed'=>true]+$extra);}public function test_admin_can_create_employee_with_role_department_and_manager():void{$admin=$this->user('admin@test.com','super_admin');$department=Department::create(['name'=>'QA','code'=>'QA']);$manager=$this->user('manager@test.com','Manager',['department_id'=>$department->id,'department'=>'QA']);$this->actingAs($admin)->post(route('admin.employees.store'),['name'=>'New Employee','email'=>'new@test.com','password'=>'password','password_confirmation'=>'password','role'=>'Executive','department_id'=>$department->id,'manager_id'=>$manager->id,'shift_time'=>'18:00','employeed'=>1])->assertRedirect(route('admin.employees.index'));$this->assertDatabaseHas('users',['email'=>'new@test.com','role'=>'Executive','department_id'=>$department->id,'manager_id'=>$manager->id]);}public function test_leave_requires_manager_then_admin_and_records_history():void{Event::fake();$department=Department::create(['name'=>'WEB','code'=>'WEB']);$manager=$this->user('manager@test.com','Manager',['department_id'=>$department->id,'department'=>'WEB']);$employee=$this->user('employee@test.com','Executive',['department_id'=>$department->id,'department'=>'WEB','manager_id'=>$manager->id]);$admin=$this->user('admin@test.com','admin');$leave=Leave::create(['user_id'=>$employee->id,'leave_type'=>'casual','start_date'=>today(),'end_date'=>today(),'status'=>'pending_manager']);$this->actingAs($manager)->patch(route('leaves.decision',[$leave,'approve']))->assertRedirect();$this->assertSame('pending_admin',$leave->fresh()->status);$this->actingAs($admin)->patch(route('leaves.decision',[$leave,'approve']))->assertRedirect();$this->assertSame('approved',$leave->fresh()->status);$this->assertNotNull($leave->fresh()->resolved_at);$this->assertSame(2,ApprovalHistory::count());}public function test_final_break_correction_creates_break_record():void{Event::fake();$employee=$this->user('employee@test.com','Executive');$admin=$this->user('admin@test.com','admin');$clock=TimeClock::create(['user_id'=>$employee->id,'clock_in'=>now()->subHours(5)]);$item=EditRequest::create(['user_id'=>$employee->id,'time_clock_id'=>$clock->id,'requested_clock_in'=>now()->subHours(4),'requested_break_in'=>now()->subHours(3),'requested_break_out'=>now()->subHours(2),'reason'=>'Forgot','status'=>'pending_admin','request_type'=>'forgot_break_start']);$this->actingAs($admin)->patch(route('edits.decision',[$item,'approve']))->assertRedirect();$this->assertDatabaseCount('breaks',1);$this->assertSame('approved',$item->fresh()->status);}}
